import{_ as e,o as i,c as r,a5 as t}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 72 话 分级自测题库","description":"","frontmatter":{},"headers":[],"relativePath":"comics/practice/EP.72-quiz.md","filePath":"comics/practice/EP.72-quiz.md","lastUpdated":1793853676000}'),o={name:"comics/practice/EP.72-quiz.md"};function l(c,a,h,d,n,s){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-72-话-分级自测题库" tabindex="-1">漫画 · 第 72 话 分级自测题库 <a class="header-anchor" href="#漫画-·-第-72-话-分级自测题库" aria-label="Permalink to &quot;漫画 · 第 72 话 分级自测题库&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/practice/02-quiz">docs/practice/02-quiz.md</a> ｜ 原画：<a href="./EP.72-quiz.svg">EP.72-quiz.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。她把文档读了三遍，自测时却说不清「为什么 <code>min-width:0</code> 能解决撑破」。</li><li><strong>码叔</strong>：老工程师。他把题目分成 L1 识记、L2 机制、L3 因果三级，要求 L3 必须写出验证方式。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>团队用题库做新人 onboarding：L1 错题超过两成的人先补布局与语义，L2 错题集中在 <code>@layer</code> 与强制同步布局，L3 用场景题做评审演练。每月复测，错题按主题统计并反哺文档。新人独立处理布局与性能问题的周期从 6 周降到 3 周。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>「都见过」是一种危险的错觉。能认出 <code>:has()</code> 的写法，不等于能解释它为什么会影响样式失效计算；能背出 LCP 的定义，不等于能判断一次依赖升级会不会拖慢首屏。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三级能力模型对应三种题型：L1 单选与判断测记忆；L2 要求解释机制，例如「分层后先比层顺序」；L3 给场景，要求同时写出原因、修复与验证。验证方式是把「掌握」与「背答案」分开的关键。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>码叔把错题按主题归档，指向具体文档与机制，而不是记选项。示例页面按 L1 / L2 / L3 抽题，即时判分并显示解析，结束时列出薄弱主题。团队每月复测，题库随浏览器基线与规范更新，避免过期题目误导。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>L1 测记忆，L2 测机制，L3 测迁移，三者不能互相替代。</li><li>错题要记录主题与机制，不只记答案。</li><li>L3 答案必须包含验证方式，否则还没真正掌握。</li><li>先做 L1 定位盲区，再做 L2、L3，不要跳级。</li><li>题库要定期更新，过期题目比没有题目更糟。</li><li>间隔重复比一次性刷题有效。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 L3 场景题要求写出「验证方式」，而不是只写原因和修复？</p><p><strong>答</strong>：原因和修复可以靠记忆复述，验证方式必须真正理解机制才能设计出来。例如判断 <code>transform</code> 动画是否更流畅，需要知道去看合成层与布局次数；判断兼容兜底是否有效，需要能强制降级复现。写不出验证，通常意味着只记住了结论。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>选择 L1 / L2 / L3 或混合模式答题，观察解析与薄弱主题记录：<a href="./../../examples/practice/02-quiz">examples/practice/02-quiz</a></li><li>故意答错几题，结束后看薄弱主题是否指向对应文档。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>五批扩展到此收官。回到漫画剧场（<code>comics/index.html</code>）从 EP.01 连续复习，或用 <a href="./../../cheatsheet">速查卡</a> 快速定位。</p>',22)])])}const q=e(o,[["render",l]]);export{p as __pageData,q as default};
